  ui_story_5003_50030201_18_dialog_content = "Voltei.",
  ui_story_5003_50030201_19_dialog_content = "Bem-vindos ao hotel. Desculpe, eu tive que sair agorinha e não pude cumprimentá-los.",
  ui_story_5003_50030201_20_dialog_content = "Vovó é a lesponsável pelo hotel!",
  ui_story_5003_50030201_21_dialog_content = "Com licença, senhora, você é do território de Astra também?",
  ui_story_5003_50030201_22_dialog_content = "Não, eu nasci e cresci aqui na Montanha Nebulosa.",
  ui_story_5003_50030201_23_dialog_content = "Você sabe quem somos?",
  ui_story_5003_50030201_24_dialog_content = "Essa é a primeira vez que nos conhecemos.",
  ui_story_5003_50030201_25_dialog_content = "Ótimo! Parece que você é uma local apesar de ser fluente em Universês!",
  ui_story_5003_50030201_26_dialog_content = "Haha, você é uma pessoa engraçada.",
  ui_story_5003_50030201_27_dialog_content = "Desculpe, é a nossa primeira vez aqui. Não estamos muito acostumados com esse lugar. Talvez tenhamos feito muitas perguntas.",
  ui_story_5003_50030201_28_dialog_content = "Não precisa ser cortês. Vocês são hóspedes do Hotel Nuvescer. Fiquem à vontade para perguntar qualquer coisa.",
  ui_story_5003_50030201_29_dialog_content = "Bem, podemos perguntar a você algo sobre o Dojo Sakae?",
  ui_story_5003_50030201_30_dialog_content = "O Dojo Sakae? Quem é você?",
  ui_story_5003_50030201_31_dialog_content = "Não importa quem sou. Eu ouvi que esse lugar originalmente era um dojo. Fiquei um pouco curiosa.",
  ui_story_5003_50030201_32_dialog_content = "Desculpe, querida hóspede, embora eu gerencie o hotel...",
  ui_story_5003_50030201_33_dialog_content = "Na verdade, eu não sou a dona. E eu não sei muito sobre esse dojo.",
  ui_story_5003_50030201_34_dialog_content = "Quando eu vim pra cá, o dojo já tinha desaparecido, deixando só um pedaço de terra aberta.",
  ui_story_5003_50030201_35_dialog_content = "Minha querida hóspede, posso saber seu nome?",
  ui_story_5003_50030201_36_dialog_content = "Eu posso perguntar por aí pra você. Se aparecer alguma coisa, eu aviso.",
  ui_story_5003_50030201_37_dialog_content = "Tudo bem. Meu nome é Hiiro.",
  ui_story_5003_50030201_38_dialog_content = "Hiiro... Que nome bonito.",
  ui_story_5003_50030201_39_dialog_content = "Tweety, você registrou nossos hóspedes e perguntou quanto tempo eles pretendem ficar?",
  ui_story_5003_50030201_40_dialog_content = "Todos se legistlalam por tlês dias!",
  ui_story_5003_50030201_41_dialog_content = "Certo. Vamos torcer pra que nossos hóspedes sejam discretos nos próximos três dias.",
