  ui_story_5003_50030201_43_dialog_content = "Além disso, por favor não comente que estamos aqui.",
  ui_story_5003_50030201_44_dialog_content = "É claro, nós nunca divulgamos informação dos nossos hóspedes pra ninguém. Fiquem tranquilos.",
  ui_story_5003_50030201_45_dialog_content = "Vocês também podem ir para a Rua Spa e perguntar lá. Talvez encontrem a informação que procuram.",
  ui_story_5003_50030201_46_dialog_content = "Andamos pela rua o dia todo e não achamos nada.",
  ui_story_5003_50030201_47_dialog_content = "Comandante Hiiro, devemos voltar e descansar primeiro antes de continuar?",
