  ui_story_5003_50030201_49_dialog_content = "Você teme que se eu encarar outro desafio, na minha condição atual, eu possa perder de novo?",
  ui_story_5003_50030201_50_dialog_content = "Desculpe.",
  ui_story_5003_50030201_51_dialog_content = "Não, não. Não precisa se desculpar. Você tem razão em se preocupar. Vamos voltar e descansar hoje.",
  ui_story_5003_50030201_52_dialog_content = "Isso é uma “fonte termal” pra você. Parece ter propriedades rejuvenescedoras.",
  ui_story_5003_50030201_53_dialog_content = "A temperatura não está diferente do que a Vice disse antes? Estou com um pouco de vertigem...",
  ui_story_5003_50030201_54_dialog_content = "Você não acabou de chegar na fonte?",
  ui_story_5003_50030201_55_dialog_content = "Sim. Eu sempre tomo banhos rápidos.",
  ui_story_5003_50030201_56_dialog_content = "Ah, espere! Você é aquele de antes? Aquele que de repente começou <color=#FFB400>um duelo com a Hiiro</color>!",
  ui_story_5003_50030201_57_dialog_content = "Aquela de cabelo rosa?",
  ui_story_5003_50030201_58_dialog_content = "O que você tá fazendo aqui? O que você quer?",
  ui_story_5003_50030201_59_dialog_content = "O nome é <color=#FFB400>\"luta\"</color>, não \"duelo\". Você precisa mesmo ter medo de mim?",
  ui_story_5003_50030201_60_dialog_content = "Eu geralmente não encontro colegas aprendizes. É natural que a gente lute. E aquela Hiiro também não concordou com isso?",
  ui_story_5003_50030201_61_dialog_content = "Hã? Eu acho que isso... meio que faz sentido?",
  ui_story_5003_50030201_62_dialog_content = "Vice, não brinque com a yukata.",
  ui_story_5003_50030201_63_dialog_content = "Você devia relaxar de vez em quando, Comandante Hiiro! Não fique tão tensa!",
  ui_story_5003_50030201_64_dialog_content = "Essas... vozes vem do banho feminino? Parece que esse lugar não é bem à prova de som.",
  ui_story_5003_50030201_65_dialog_content = "Não mesmo.",
  ui_story_5003_50030201_66_dialog_content = "Então vamos conversar em outro lugar.",
  ui_story_5003_50030201_67_dialog_content = "Falando nisso, a Comandante Hiiro é como uma flor de cerejeira.",
  ui_story_5003_50030201_68_dialog_content = "Eu concoldo! Hiilo é desse jeito!",
  ui_story_5003_50030201_69_dialog_content = "Talvez seja porque sou membro da <color=#FFB400>Família Sakura</color>.",
  ui_story_5003_50030201_70_dialog_content = "A família Sakula? A Vovó me falou dela. Essa é uma <color=#FFB400>misteliosa e podelosa</color> família.",
  ui_story_5003_50030201_71_dialog_content = "Mas os Sakulas são... Eles não desapalecelam há muito tempo?",
  ui_story_5003_50030201_72_dialog_content = "De fato. Eles sumiram há muito tempo. A época dos Sakuras foi curta, mas eles encararam a morte com bravura inabalável.",
  ui_story_5003_50030201_73_dialog_content = "Eu já era a última da minha linhagem bem antes de me tornar adulta.",
  ui_story_5003_50030201_74_dialog_content = "Sinto muito. Eu não quis tlazer à tona uma memólia tão tliste.",
  ui_story_5003_50030201_75_dialog_content = "Não se preocupe. Não é uma memória particularmente triste pra mim.",
  ui_story_5003_50030201_76_dialog_content = "Fui criada pelo meu mestre, então eu me lembro bem sobre a Família Sakura.",
  ui_story_5003_50030201_77_dialog_content = "Meu mestre é a coisa mais próxima de família pra mim. Não me preocupo muito com minha família biológica.",
  ui_story_5003_50030201_78_dialog_content = "Além disso, poder voltar para minha cidade natal assim e ver as flores de cerejeira aqui é o suficiente pra mim.",
  ui_story_5003_50030201_79_dialog_content = "Desculpe, achei que você seguiu a gente até o hotel.",
  ui_story_5003_50030201_80_dialog_content = "Mas pensando nisso, você está vestindo uma yukata. Então você deve ser um hóspede aqui.",
  ui_story_5003_50030201_81_dialog_content = "Sim. Mas, precisamente, eu sou um investidor desse hotel. Aqui está meu cartão de visita.",
  ui_story_5003_50030201_82_dialog_content = "Você é um dos investidores do hotel? Mas o seu cartão de visita diz que você trabalha em Umbraton!?",
  ui_story_5003_50030201_83_dialog_content = "Pode me chamar de Taki. Eu tenho uma empresa em Umbraton. Você pode vir e me encontrar se tiver negócios aqui no futuro.",
  ui_story_5003_50030201_84_dialog_content = "Já foi uma surpresa saber que a Tweety é da União Mensageira, e agora, você é de Astra.",
  ui_story_5003_50030201_X84_dialog_content = "Mas agora eu sinto que encontrar pessoas de algum lugar familiar é na verdade bem confortante.",
  ui_story_5003_50030201_85_dialog_content = "Sou PlayerName. Fico feliz de te encontrar desse jeito. Assim como sei que você vai ajudar bastante a nossa investigação aqui.",
  ui_story_5003_50030201_86_dialog_content = "Humm, ideia interessante. Vou te cobrar isso hein.",
  ui_story_5003_50030201_87_dialog_content = "Isso inclui consultas também?",
  ui_story_5003_50030201_88_dialog_content = "Agora já chega disso. Hiiro e eu somos do Dojo Sakae. Você sabe, né?",
  ui_story_5003_50030201_89_dialog_content = "Eu sei. Hiiro nos contou algo sobre o dojo.",
  ui_story_5003_50030201_90_dialog_content = "Hum, parece que vocês são pessoas em quem posso confiar.",
  ui_story_5003_50030201_91_dialog_content = "<anim type=Shake><color=#e8d9bb>*Zuuup*</color></anim>",
  ui_story_5003_50030201_92_dialog_content = "Ei, alguém correu lá pra fora?",
  ui_story_5003_50030201_93_dialog_content = "Hã? Quem?",
  ui_story_5003_50030201_94_dialog_content = "Não sei. Não os reconheci.",
  ui_story_5003_50030201_95_dialog_content = "Vou checar!",
  ui_story_5003_50030201_96_dialog_content = "<size=30>Hã? Quer dizer que alguém...</size>",
  ui_story_5003_50030201_97_dialog_content = "(Vice e os outros parecem estar conversando sobre alguma coisa no banho feminino.)",
  ui_story_5003_50030201_98_dialog_content = "<size=30>Shh! Que barulho é esse lá fora? Tweety, não vá pra lá ainda. Vamos...</size>",
  ui_story_5003_50030201_99_dialog_content = "Vice, tá tudo bem aí com vocês?",
  ui_story_5003_50030201_100_dialog_content = "PlayerName? Você...",
  ui_story_5003_50030201_101_dialog_content = "Acabei de voltar de lá fora para ver se tinha algo errado.",
  ui_story_5003_50030201_102_dialog_content = "Tentando espiar? Eu nunca imagine...",
  ui_story_5003_50030201_103_dialog_content = "Hã? O que foi?",
  ui_story_5003_50030201_104_dialog_content = "Qu-qu-quê? Você estava tentando espiar?",
  ui_story_5003_50030201_105_dialog_content = "Espiar? Não, não é nada disso! Não olhei lá dentro!",
  ui_story_5003_50030201_106_dialog_content = "Eu só vi uma pessoa suspeita correndo lá fora. Então eu vim ver o que aconteceu.",
  ui_story_5003_50030201_107_dialog_content = "É que esse lugar não é à prova de som. Eu sem querer escutei...",
  ui_story_5003_50030201_108_dialog_content = "O que você ouviu?",
  ui_story_5003_50030201_109_dialog_content = "Primeiro, eu ouvi: “Não brinque com a yukata”. Não, eu não estava espiando!",
  ui_story_5003_50030201_110_dialog_content = "PlayerName! Diga a verdade!",
  ui_story_5003_50030201_111_dialog_content = "Espere! Vice! Eu não espiei mesmo!",
  ui_story_5003_50030201_112_dialog_content = "Então, quem estava espiando do lado de fora?",
  ui_story_5003_50030201_113_dialog_content = "Eu acho... que era uma criança?",
  ui_story_5003_50030201_114_dialog_content = "Você quer dizer uma criança como você?",
  ui_story_5003_50030201_115_dialog_content = "Não! Eu acho que a pessoa que saiu do hotel era quem estava espiando!",
  ui_story_5003_50030201_116_dialog_content = "Eu me lembro de ver um garoto sem camisa com cabelo comprido. Talvez ele estivesse na Rua Spa!",
  ui_story_5003_50030201_117_dialog_content = "Nós não temos nenhuma garota aqui com cabelo comprido.",
  ui_story_5003_50030201_118_dialog_content = "PlayerName, você não está mentindo pra mim, está?",
  ui_story_5003_50030201_119_dialog_content = "É claro que não!",
  ui_story_5003_50030201_X119_dialog_content = "Espere. Tenho certeza que consigo reconhecê-lo se eu o vir de novo. Vamos confrontá-lo juntos!",
  ui_story_5003_50030301_1_dialog_content = "Mestre, por que as pessoas ficaram contra o dojo?",
  ui_story_5003_50030301_2_dialog_content = "Quando enfrentamos uma crise, todos fazemos o que podemos para sobreviver.",
  ui_story_5003_50030301_3_dialog_content = "Se a vontade de sobreviver se concentra em uma coisa em particular, isso pode gerar conflito.",
  ui_story_5003_50030301_4_dialog_content = "Nós fugimos para nos afastar desse conflitos perigosos.",
  ui_story_5003_50030301_5_dialog_content = "Mas você sempre me ensinou a nunca ter medo da morte e lutar bravamente até o fim. Mas, Mestre... nós fugimos?",
  ui_story_5003_50030301_6_dialog_content = "Fugir nem sempre é um ato de covardia e nem é um abandono de responsabilidade de alguém. O motivo pelo qual fiz o que fiz...",
  ui_story_5003_50030301_7_dialog_content = "É porque eu tinha algo mais importante pra proteger. Eu tinha que manter a <color=#FFB400>chave</color> a salvo, Hiiro.",
  ui_story_5003_50030301_8_dialog_content = "Quando vamos voltar? Quando os conflitos vão acabar?",
  ui_story_5003_50030301_9_dialog_content = "Hiiro, nós não vamos voltar.",
  ui_story_5003_50030301_10_dialog_content = "Comandante Hiiro, tudo bem? Está com dificuldades pra dormir de novo?",
  ui_story_5003_50030301_11_dialog_content = "Não, estou bem. Estava só pensando em algo.",
  ui_story_5003_50030301_12_dialog_content = "Vocês acordam tão cedo! Desculpem, não tive tempo pra preparar o café da manhã pra vocês.",
  ui_story_5003_50030301_13_dialog_content = "Desculpe, senhora. Nós queríamos sair mais cedo e não tínhamos a intenção de atrapalhá-los.",
  ui_story_5003_50030301_14_dialog_content = "Não diga isso. Isso é tudo parte do serviço aqui.",
  ui_story_5003_50030301_15_dialog_content = "Não se preocupe com a gente. Tem algo que precisamos investigar nas ruas.",
  ui_story_5003_50030301_16_dialog_content = "Então... Vocês gostariam de tomar café quando voltarem? Tweety e eu vamos ao mercado comprar alguns ingredientes bons.",
  ui_story_5003_50030301_17_dialog_content = "Vocês são muito gentis. Mas vamos comer fora.",
  ui_story_5003_50030301_18_dialog_content = "Tudo bem, tudo bem.",
  ui_story_5003_50030301_19_dialog_content = "PlayerName, vamos começar nossa investigação com o hotel.",
  ui_story_5003_50030301_20_dialog_content = "Na verdade, aproveitamos nosso tempo na fonte termal ontem para perguntar ao Tweety sobre o hotel.",
  ui_story_5003_50030301_21_dialog_content = "Não notamos nada suspeito. Embora a velhinha gerencie o hotel, ela não é a proprietária.",
  ui_story_5003_50030301_22_dialog_content = "De modo geral, não há nada estranho em comprar um terreno pra construir um novo negócio.",
  ui_story_5003_50030301_23_dialog_content = "Contudo, há algo especial sobre o terreno em que o dojo foi construído.",
  ui_story_5003_50030301_24_dialog_content = "No Oriente, chamamos um lugar assim de “terra profana”.",
  ui_story_5003_50030301_25_dialog_content = "Veja bem, pessoas tendem a evitar lugares nos quais incidentes horríveis aconteceram.",
  ui_story_5003_50030301_26_dialog_content = "Evitá-los? Parece que no hotel não há nenhum outro hóspede.",
  ui_story_5003_50030301_27_dialog_content = "A Família Sakae foi praticamente dizimada durante a noite. Um incêndio queimou o dojo, deixando só ruínas em seu lugar.",
  ui_story_5003_50030301_28_dialog_content = "Quem gostaria de comprar um terra encharcada em sangue e construir uma fonte termal sem clientes?",
  ui_story_5003_50030301_29_dialog_content = "Precisamos achar o investidor. A velhinha nos disse que ele pode ser encontrado na Rua Spa",
  ui_story_5003_50030301_30_dialog_content = "Seu nome é...",
  ui_story_5003_50030301_31_option_content = "Taki! Eu o conheço!",
  ui_story_5003_50030301_32_dialog_content = "PlayerName, como você sabe o nome do investidor?",
  ui_story_5003_50030301_33_dialog_content = "Ele me disse ontem que era um investidor! Hiiro, foi ele quem “lutou” com você! Seu antigo colega de dojo!",
  ui_story_5003_50030301_34_dialog_content = "Aquele cara?",
  ui_story_5003_50030301_35_dialog_content = "Onde você estava ontem? Como você esbarrou nele?",
  ui_story_5003_50030301_36_dialog_content = "Eu o encontrei no hotel. Eu disse oi e nós acabamos conversando.",
  ui_story_5003_50030301_37_dialog_content = "Você não perguntou pra ele do hotel?",
  ui_story_5003_50030301_38_dialog_content = "Não... Nossa conversa foi interrompida quando eu vi alguém correndo do lado de fora do hotel.",
  ui_story_5003_50030301_39_dialog_content = "Desculpe, eu achei mesmo que você estava espiando a gente quando estávamos do lado de fora do banho feminino, ontem.",
  ui_story_5003_50030301_40_dialog_content = "É claro que eu não estava! Eu só me preocupei porque se algo estivesse acontecendo, vocês seriam pegas de surpresa.",
  ui_story_5003_50030301_41_dialog_content = "Então decidi ir primeiro e ver o que estava acontecendo.",
  ui_story_5003_50030301_42_dialog_content = "Hã? É veldade mesmo que você espiou ontem??",
  ui_story_5003_50030301_43_dialog_content = "Não, eu só estava ouvindo... Quero dizer, não! Eu não vi nada!",
  ui_story_5003_50030301_44_dialog_content = "Tweety, o que você está fazendo aqui?",
  ui_story_5003_50030301_45_dialog_content = "É minha vez de pegar os mantimentos!",
  ui_story_5003_50030301_46_dialog_content = "Então Piu-Piu também é responsável pelas compras de supermercado.",
  ui_story_5003_50030301_47_dialog_content = "Tweety, você conhece o Taki?",
  ui_story_5003_50030301_48_dialog_content = "Conheço sim! Eu posso plocular por ele, se você quiser!",
  ui_story_5003_50030301_49_dialog_content = "Beleza, estamos contando com você pra nos ajudar a achá-lo.",
  ui_story_5003_50030301_50_dialog_content = "Nós ficamos na rua o dia todo e não encontramos nada, assim como ontem...",
  ui_story_5003_50030301_51_dialog_content = "Que estlanho. Não consigo encontlar o Senhor Taki hoje. O Mestle desapaleceu de uma hola pla outla?",
  ui_story_5003_50030301_52_dialog_content = "Taki estava ao ledor da Lua Spa nos últimos dias. Talvez ele foi pla outlo lugar hoje?",
  ui_story_5003_50030301_53_dialog_content = "Ele estava <color=#FFB400>passeando pela Rua Spa</color>? O que ele estava fazendo?",
  ui_story_5003_50030301_54_dialog_content = "Senhor Taki diz que já faz um tempo desde que ele voltou, então ele quelia passear e depois voltava.",
  ui_story_5003_50030301_55_dialog_content = "Olhem a hola. Que tal todos voltalem e descansalem plimeilo?",
  ui_story_5003_50030301_56_dialog_content = "Eu vou dar um piu quando o Senhor Taki voltar.",
  ui_story_5003_50030301_57_dialog_content = "Se ele ouvir que queremos vê-lo... Provavelmente ele vai suspeitar de algo e vai evitar nos encontrar.",
  ui_story_5003_50030301_58_option_content = "Acho que tem razão.",
  ui_story_5003_50030301_59_dialog_content = "Quando nos encontramos ontem, ele estava um pouco surpreso e perguntou: “Você não acabou de chegar na fonte?”",
  ui_story_5003_50030301_60_option_content = "Acho que não.",
  ui_story_5003_50030301_61_dialog_content = "Quando eu vi o Taki ontem, ele parecia bem calmo quando falava do dojo.",
  ui_story_5003_50030301_62_dialog_content = "Eu não acho que ele tenha nada a esconder.",
  ui_story_5003_50030301_63_dialog_content = "Bem, talvez o Sr. Taki já tenha voltado pro hotel?",
  ui_story_5003_50030301_64_dialog_content = "Talvez nós não o vimos na rua porque nos desencontramos.",
  ui_story_5003_50030301_65_dialog_content = "Veldade, veldade!",
  ui_story_5003_50030301_66_dialog_content = "Quando o Taki voltar pro hotel, a primeira coisa que você vai fazer é nos avisar, certo, Tweety?",
  ui_story_5003_50030301_67_dialog_content = "É clalo! Pode confiar em mim!",
  ui_story_5003_50030301_68_dialog_content = "Beleza, vamos voltar pro hotel então.",
  ui_story_5003_50030301_69_dialog_content = "PlayerName, posso pedir pra você ficar de olho se notar algo estranho?",
  ui_story_5003_50030301_70_dialog_content = "Algo estranho?",
  ui_story_5003_50030301_71_dialog_content = "Isso mesmo. Eu acho que sua habilidade psíquica pode ser útil aqui.",
  ui_story_5003_50030301_72_dialog_content = "Ok. Entendi.",
  ui_story_5003_50030301_73_dialog_content = "Gha... Graaaah...",
  ui_story_5003_50030301_74_dialog_content = "Er... Acho que eu ouvi algo estranho vindo do...",
  ui_story_5003_50030301_75_dialog_content = "*Rugido*",
  ui_story_5003_50030301_76_dialog_content = "Ahhh! Eclipsitas!",
  ui_story_5003_50030301_77_dialog_content = "*Rugindo*",
  ui_story_5003_50030301_78_dialog_content = "Como? O que esses Eclipsitas estão fazendo na Lua Spa?",
  ui_story_5003_50030301_79_dialog_content = "Ah não! Eles são muitos!",
  ui_story_5003_50030301_80_dialog_content = "Esses Eclipsitas não são tão foltes! Eu posso ajudar!",
  ui_story_5003_50030301_81_dialog_content = "Para trás! Voltem pro hotel. O caminho é estreito aqui! Bloqueiem!",
  ui_story_5003_50030301_82_dialog_content = "PlayerName, vá e avise a velhinha. Nós vamos cuidar dos Eclipsitas do lado de fora!",
  ui_story_5003_50030301_83_dialog_content = "Vamos!",
  ui_story_5003_50030301_84_dialog_content = "*Rugindo*",
  ui_story_5003_50030301_85_dialog_content = "Ah não! Comandante Hiiro! Eclipsitas estão indo para a rua!",
  ui_story_5003_50030301_86_dialog_content = "Eu vou impedi-los!",
  ui_story_5003_50030301_87_dialog_content = "Gaah... Graaah...",
  ui_story_5003_50030301_88_dialog_content = "Quem está aí? Apareça!",
  ui_story_5003_50030301_89_dialog_content = "Nos encontramos de novo, Hiiro.",
  ui_story_5003_50030301_90_dialog_content = "Senhora! Senhora, onde você está? Senhora!?",
  ui_story_5003_50030301_91_dialog_content = "Estranho... Não tem ninguém no hotel?",
  ui_story_5003_50030301_92_dialog_content = "Espere...",
  ui_story_5003_50030301_X92_dialog_content = "Quem está se escondendo no pátio? Apareça!",
  ui_story_5003_50030301_93_dialog_content = "Você é...",
  ui_story_5003_50030301_94_dialog_content = "...",
  ui_story_5003_50030301_95_dialog_content = "Você é o cara que veio correndo do lado de fora na última noite, né?",
  ui_story_5003_50030301_96_dialog_content = "Gaah... Graaah...",
  ui_story_5003_50030301_97_dialog_content = "Os Eclipsitas já foram quase todos derrotados. Sobre o que você queria falar comigo? Vá em frente e diga.",
  ui_story_5003_50030301_98_dialog_content = "Taki, por que você construiria um hotel no terreno do Dojo Sakae?",
  ui_story_5003_50030301_99_dialog_content = "A única razão que posso pensar é que você queria esconder algo.",
  ui_story_5003_50030301_100_dialog_content = "O Dojo Sakae não existe mais. O terreno estava disponível, então, naturalmente, eu comprei.",
  ui_story_5003_50030301_101_dialog_content = "O que você disse?!",
  ui_story_5003_50030301_102_dialog_content = "Acalme-se. Se você vai deixar suas emoções te controlarem, eu aconselho você a esquecer esse tipo de pergunta.",
  ui_story_5003_50030301_103_dialog_content = "A Família Sakae foi massacrada pelos <color=#FFB400>inimigos</color>. Mestre não teve outra escolha a não ser fugir comigo e você quer que eu me acalme?",
  ui_story_5003_50030301_104_dialog_content = "<size=45>Eu vim me vingar!</size>",
  ui_story_5003_50030301_105_dialog_content = "Você nem é capaz de diferenciar um amigo do inimigo agora. Eu já te disse, sou seu colega aprendiz.",
  ui_story_5003_50030301_106_dialog_content = "Está vendo essa cicatriz no meu rosto? Foi seu mestre quem fez, o líder do Dojo Sakae, <color=#FFB400>Sakae Shigeo</color>.",
  ui_story_5003_50030301_107_dialog_content = "Meu mestre? Mas, por quê?",
  ui_story_5003_50030301_108_dialog_content = "Sakae Shigeo achava que eu muito magro e fraco. O olhar nos seus olhos me dizia que eu não seria aceito como aprendiz.",
  ui_story_5003_50030301_109_dialog_content = "Então eu o ataquei e ele me cortou. Mas ele também admitiu que eu tinha potencial.",
  ui_story_5003_50030301_110_dialog_content = "Então ele aceitou você como aprendiz do Dojo Sakae?",
  ui_story_5003_50030301_111_dialog_content = "Sim. Eu jurei a Sakae Shigeo que se eu não pudesse derrotá-lo em três anos, eu sairia por conta própria.",
  ui_story_5003_50030301_112_dialog_content = "E eu não contaria a ninguém que fui aprendiz do clã Sakae para não envergonhá-lo.",
  ui_story_5003_50030301_113_dialog_content = "Você venceu no final?",
  ui_story_5003_50030301_114_dialog_content = "Não, ele me deixou vencer. No fim, eu sai da Montanha Nebulosa e fui para a terra firme.",
  ui_story_5003_50030301_115_dialog_content = "Eu não contei a ninguém que sou aprendiz do clã Sakae para que não suspeitassem de mim sem motivos.",
  ui_story_5003_50030301_116_dialog_content = "Foi você quem me atacou primeiro. Eu só suspeitei de você porque eu não sabia a verdade.",
  ui_story_5003_50030301_117_dialog_content = "Nós só estávamos lutando. Eu não queria te machucar. Mesmo se você não me conhecesse, você devia conhecer o estilo Sakae.",
  ui_story_5003_50030301_118_dialog_content = "Eu só recebi a notícia após a queda do Dojo Sakae.",
  ui_story_5003_50030301_119_dialog_content = "Tudo o que eu podia fazer era comprar o terreno em que o dojo ficava pra que ele não caísse nas mãos de outrem.",
  ui_story_5003_50030301_120_dialog_content = "Em nosso primeiro encontro, você disse: <color=#FFB400>\"A Montanha Nebulosa está segura agora.\"</color> O que quis dizer?",
  ui_story_5003_50030301_121_dialog_content = "Eu fiz umas investigações. Os assassinos do dojo já tinham ido embora.",
  ui_story_5003_50030301_122_dialog_content = "O que aconteceu com eles?",
  ui_story_5003_50030301_123_dialog_content = "Eles foram mortos. Ou talvez os aprendizes do Dojo Sakae lutaram bravamente e morreram durante a batalha.",
  ui_story_5003_50030301_124_dialog_content = "Morreram juntos na batalha? Então, quer dizer... Meus inimigos já foram derrotados antes de eu voltar?",
  ui_story_5003_50030301_125_dialog_content = "Correto. Já está tudo acabado.",
  ui_story_5003_50030301_126_dialog_content = "Éramos do mesmo dojo, afinal. Estou te contando isso porque eu não quero que seja uma escrava do passado.",
  ui_story_5003_50030301_127_dialog_content = "...",
  ui_story_5003_50030301_128_dialog_content = "A velhinha veio até mim e disse que ela queria comprar o hotel.",
  ui_story_5003_50030301_129_dialog_content = "Quer dizer... Não foi você que quis construir o hotel nesse terreno? Foi ela?",
  ui_story_5003_50030301_130_dialog_content = "O que ela está tentando esconder comprando um hotel nas ruínas de um dojo?",
  ui_story_5003_50030401_1_dialog_content = "Criança tola... O que você está fazendo caída na minha porta assim? Você não faz uma refeição há algum tempo, ein?",
  ui_story_5003_50030401_2_dialog_content = "Era você... que estava de guarda dois dias atrás?",
  ui_story_5003_50030401_3_dialog_content = "Isso mesmo. Você acha que sou muito velho para lutar?",
  ui_story_5003_50030401_4_dialog_content = "Você deve estar brincando...",
  ui_story_5003_50030401_X4_dialog_content = "<size=45>Eu deixei você escapar muito fácil! Você realmente acha que é melhor do que eu!?</size>",
  ui_story_5003_50030401_5_dialog_content = "Hehe, acalme-se e entre. O jantar está pronto.",
  ui_story_5003_50030401_6_dialog_content = "Você vai deixar eu entrar?",
  ui_story_5003_50030401_7_dialog_content = "Por que eu não deixaria?",
  ui_story_5003_50030401_X7_dialog_content = "Isso é um hotel.",
  ui_story_5003_50030401_8_dialog_content = "Onde estou? Quem é você?",
  ui_story_5003_50030401_9_dialog_content = "Isso é um dojo. Eu sou Sanki.",
  ui_story_5003_50030401_10_dialog_content = "Por que você me amarrou? O que vai fazer comigo?",
  ui_story_5003_50030401_11_dialog_content = "Para evitar que você se debatesse.",
  ui_story_5003_50030401_12_dialog_content = "Então, o que vai fazer comigo?",
  ui_story_5003_50030401_13_dialog_content = "Silêncio. Você acha que sou idiota? Sou eu que faço as perguntas aqui.",
  ui_story_5003_50030401_14_dialog_content = "Ok, se você diz... Mas o que você quis dizer quando falou que isso é um dojo?",
  ui_story_5003_50030401_15_dialog_content = "Eu achei que o dojo tinha sido destruído há muito tempo. Não pode ser esse local.",
  ui_story_5003_50030401_16_dialog_content = "Não pode ser o dojo é?",
  ui_story_5003_50030401_X16_dialog_content = "Hahahaha!",
  ui_story_5003_50030401_17_dialog_content = "Você nunca viu o dojo. Parece que você não sabe de nada mesmo.",
  ui_story_5003_50030401_S18_dialog_content = "O dojo foi destruído, mas parte dele ainda existe escondido debaixo do Hotel Nuvescer.",
  ui_story_5003_50030401_S19_dialog_content = "Desculpe, eu realmente não sei de nada. Por que você não me conta mais?",
  ui_story_5003_50030401_S20_dialog_content = "Cale-se! Eu já disse o bastante! Você acha que sou idiota!?",
  ui_story_5003_50030401_S21_dialog_content = "Desculpe! Tudo bem se você não quiser falar sobre o dojo. Vamos mudar de assunto.",
  ui_story_5003_50030401_X18_dialog_content = "Sua lâmina é bem legal. Todo mundo no Oriente tem uma espada?",
  ui_story_5003_50030401_19_dialog_content = "Já falei pra você calar a boca! Eu nem estava procurando por você! Pare de tentar puxar assunto!",
  ui_story_5003_50030401_20_dialog_content = "...!",
  ui_story_5003_50030401_21_dialog_content = "(Esse cara acertou alguém mesmo. Se eu soubesse... Eu teria parado de falar.)",
  ui_story_5003_50030401_22_dialog_content = "PlayerName? PlayerName? Onde você está?",
  ui_story_5003_50030401_23_dialog_content = "PlayerName? Vovó? Onde vocês estão?",
  ui_story_5003_50030401_24_dialog_content = "Vice, o que tá acontecendo?",
  ui_story_5003_50030401_25_dialog_content = "PlayerName e a velhinha não estão no hotel... Mas ele estava indo para aquela direção agorinha.",
  ui_story_5003_50030401_26_dialog_content = "Vamos olhar de novo.",
  ui_story_5003_50030401_27_dialog_content = "Vice! Hiilo! Ploblema!",
  ui_story_5003_50030401_28_dialog_content = "O que foi?",
  ui_story_5003_50030401_29_dialog_content = "Eu não consegui encontlar a Vovó, mas encontlei uma nota!",
  ui_story_5003_50030401_30_dialog_content = "Descendente da Família Sakura: Deixe a Montanha Nebulosa imediatamente!",
  ui_story_5003_50030401_X30_dialog_content = "Caso contrário, algo terrível vai acontecer com você e seus amigos viajantes!",
  ui_story_5003_50030401_31_dialog_content = "Além disso, se quiser ver PlayerName com vida de novo, vá para a Rua Spa e espere.",
  ui_story_5003_50030401_32_dialog_content = "Alguém fez o PlayerName de refém!?",
  ui_story_5003_50030401_33_dialog_content = "<color=#e8d9bb>*Balança, balança... Quebra, quebra...*</color>",
  ui_story_5003_50030401_34_dialog_content = "(Parece que tem algo... <color=#FFB400>balançando</color>?)",
  ui_story_5003_50030401_35_dialog_content = "... Quem está aí!?",
  ui_story_5003_50030401_36_dialog_content = "Esse som tá vindo lá de fora? Sanki... Ele saiu!)",
  ui_story_5003_50030401_37_dialog_content = "(Agora é a minha chance de escapar dessa confusão!)",
  ui_story_5003_50030401_38_dialog_content = "(Eu mal consigo me mexer... Espere aí, posso chamar alguém com minhas habilidades psíquicas!)",
  ui_story_5003_50030401_39_dialog_content = "<color=#e8d9bb>*clique... clique... shoom...*</color>",
  ui_story_5003_50030401_40_dialog_content = "(Não acredito... Ele já voltou?)",
  ui_story_5003_50030401_41_dialog_content = "Espere... É...!",
  ui_story_5003_50030401_42_dialog_content = "Vovó!?",
  ui_story_5003_50030401_43_dialog_content = "Silêncio, fique quieta, criança.",
  ui_story_5003_50030401_44_dialog_content = "O que está fazendo aqui?",
  ui_story_5003_50030401_45_dialog_content = "Eu explico depois. Deixe-me desamarrar essas cordas primeiro. Vamos sair daqui.",
  ui_story_5003_50030401_46_dialog_content = "O que tá acontecendo aqui?",
  ui_story_5003_50030401_47_dialog_content = "Meu jovem, espero que não culpe Sanki pelo que ele fez. <color=#FFB400>Ele só quer proteger a Montanha Nebulosa</color>.",
  ui_story_5003_50030401_48_dialog_content = "Proteger do quê?",
  ui_story_5003_50030401_49_dialog_content = "Desculpe, mas não posso contar todos os segredos da Montanha Nebulosa. Porém, eu posso explicar parte do motivo pra você.",
  ui_story_5003_50030401_50_dialog_content = "A Montanha Nebulosa é protegida por uma barreira externa, mas a sua chegada a afetou de alguma forma, fazendo com que os Eclipsitas entrassem.",
  ui_story_5003_50030401_51_dialog_content = "Sanki tentando forçar você a ir embora porque trouxe perigo para a Montanha Nebulosa...",
  ui_story_5003_50030401_52_dialog_content = "Eu já tinha dado uma bronca nele. Eu espero que possa perdoá-lo pelo que ele fez.",
  ui_story_5003_50030401_53_dialog_content = "Mas eu não entendo. Por que nossa presença aqui afetou a barreira?",
  ui_story_5003_50030401_54_dialog_content = "Vamos lá pra fora primeiro. Eu vou explicar pra você quando nos encontrarmos com a Hiiro, tá?",
  ui_story_5003_50030401_55_dialog_content = "OK.",
  ui_story_5003_50030401_56_dialog_content = "PlayerName? Onde você está? Estávamos te procurando há tempos!",
  ui_story_5003_50030401_57_dialog_content = "Você... não foi esperar na Rua Spa?",
  ui_story_5003_50030401_58_dialog_content = "Rua Spa?",
  ui_story_5003_50030401_59_dialog_content = "Parece que a velhinha escreveu um recado pedindo pra gente ir embora.",
  ui_story_5003_50030401_60_dialog_content = "Desculpem. Mas eu achei que seria melhor se vocês saíssem da Montanha Nebulosa.",
  ui_story_5003_50030401_61_dialog_content = "Você pode explicar o que está acontecendo aqui, Vovó?",
  ui_story_5003_50030401_62_dialog_content = "Por que você construiu um hotel no terreno do Dojo?",
  ui_story_5003_50030401_63_dialog_content = "Bem, eu construí o hotel para proteger o dojo.",
  ui_story_5003_50030401_65_dialog_content = "Imagino que não tenha como esconder isso de você, mas isso é só entre Hiiro e aqueles em quem ela confia.",
  ui_story_5003_50030401_66_dialog_content = "Venha comigo, Tweety.",
  ui_story_5003_50030401_67_dialog_content = "Tudo bem. Não se pleocupe, Vovó. Eu vou vigiar a lua! Não vou deixar ninguém entlar!",
  ui_story_5003_50030401_68_dialog_content = "Boa criança. Obrigada.",
  ui_story_5003_50030401_69_dialog_content = "Você não devia ter voltado, Hiiro.",
  ui_story_5003_50030401_70_dialog_content = "Sakae Shigeo não deixaria você voltar.",
  ui_story_5003_50030401_71_dialog_content = "Vovó... Quem é você?",
  ui_story_5003_50030401_72_dialog_content = "Quando eu era jovem, eu costumava ser a empregada da Família Sakura e também a mensageira que entregava informação secreta.",
  ui_story_5003_50030401_73_dialog_content = "A Família Sakura e a Família Sakae eram as duas principais forças guardiãs da barreira da Montanha Nebulosa.",
  ui_story_5003_50030401_74_dialog_content = "As duas famílias chamaram o carpinteiro mais habilidoso em Underwell pra construir uma sala secreta no dojo.",
  ui_story_5003_50030401_75_dialog_content = "Eles selaram algo muito importante aqui. Algo que contém um poder imenso e mantém a barreira.",
  ui_story_5003_50030401_76_dialog_content = "Só quando as duas famílias estiverem aqui, seu sangue poderá ser usado para remover o selo.",
  ui_story_5003_50030401_77_dialog_content = "Mas uma vez que o selo for removido, a estabilidade da barreira será destruída pelo imenso poder desse “objeto importante”.",
  ui_story_5003_50030401_78_dialog_content = "E Eclipsitas vão surgir como uma avalanche.",
  ui_story_5003_50030401_79_dialog_content = "No desespero para obter o “objeto”, <color=#FFB400>o ressentimento das forças do mal do Oriente contra a Família Sakae</color> cresceu.",
  ui_story_5003_50030401_80_dialog_content = "Naquela noite fatídica, o Dojo Sakae foi atacado.",
  ui_story_5003_50030401_81_dialog_content = "<color=#FFB400>A sala secreta fica no subsolo</color>, e o selo estava encharcado com o sangue da família Sakae.",
  ui_story_5003_50030401_82_dialog_content = "Hiiro, você é a última da sua linhagem, só ficar aqui vai afetar o selo.",
  ui_story_5003_50030401_83_dialog_content = "Eu só voltei pra Montanha Nebulosa para investigar coisas sobre a Família Sakae.",
  ui_story_5003_50030401_84_dialog_content = "<size=45>Sua existência representa o maior segredo da Família Sakae e Sakura</size>.",
  ui_story_5003_50030401_85_dialog_content = "Eu te reconheci assim que vi você. Você me lembra sua mãe e sua avó.",
  ui_story_5003_50030401_86_dialog_content = "Eu cresci com a sua avó, mas elas morreram há muito tempo.",
  ui_story_5003_50030401_87_dialog_content = "Está é uma carta da sua mãe. Ela prova que o que eu disse é verdade.",
  ui_story_5003_50030401_88_dialog_content = "Agora vão. Fiquem longe daqui antes que os Eclipsitas organizem outro ataque.",
  ui_story_5003_50030401_89_dialog_content = "Então se eu for embora, a Montanha Nebulosa ficará a salvo?",
  ui_story_5003_50030401_90_dialog_content = "Sim.",
  ui_story_5003_50030401_91_option_content = "Por que você não vem com a gente?",
  ui_story_5003_50030401_92_dialog_content = "Perdão, mas eu não posso ir com vocês.",
  ui_story_5003_50030401_93_dialog_content = "Devo ficar aqui para vigiar o hotel e a sala secreta embaixo dele.",
  ui_story_5003_50030401_94_option_content = "Hiiro, o que você vai fazer?",
  ui_story_5003_50030401_95_dialog_content = "Entendo. Saber que você está aqui fez toda essa jornada valer a pena.",
  ui_story_5003_50030401_96_dialog_content = "Vou sair da Montanha Nebulosa, mas temo que os Eclipsitas possam invadir novamente.",
  ui_story_5003_50030401_97_dialog_content = "Então, gostaria de pedir para Vice e PlayerName ficarem aqui por enquanto para garantir a segurança de todos.",
  ui_story_5003_50030401_98_dialog_content = "O quê? Sem a Colossus... Como você pretende sair daqui sozinha, Hiiro?",
  ui_story_5003_50030401_99_dialog_content = "Não se preocupem. Eu vou para o porto sozinha.",
  ui_story_5003_50030401_100_dialog_content = "Hiiro, as pessoas aqui estão muito apreensivas com a sua presença.",
  ui_story_5003_50030401_101_dialog_content = "Elas dizem que você trouxe os Eclipsitas e a calamidade para a Montanha Nebulosa.",
  ui_story_5003_50030401_102_dialog_content = "Sanki até atacou PlayerName.",
  ui_story_5003_50030401_X102_dialog_content = "É por isso que acho que todos vocês deviam ir embora juntos.",
  ui_story_5003_50030401_103_dialog_content = "Eu nunca pensei que nossa viagem para a Montanha Nebulosa acabaria desse jeito.",
  ui_story_5003_50030401_104_dialog_content = "Silêncio, não fale de PlayerName ou a Comandante Hiiro vai ficar chateada.",
  ui_story_5003_50030401_105_dialog_content = "Você não precisa se preocupar comigo. Eu aceito qualquer desfecho que a jornada possa ter.",
  ui_story_5003_50030401_106_dialog_content = "Nós encontramos o Sr. Taki e a Tweety. Isso vai facilitar muito as coisas pra gente, se precisarmos investigar a Montanha Nebulosa futuramente.",
  ui_story_5003_50030401_107_dialog_content = "E eu li aquela carta. Eu acredito que a Vovó disse a verdade.",
  ui_story_5003_50030401_108_dialog_content = "Eu aprendi sobre a história dela e a história da minha família. A jornada valeu a pena.",
  ui_story_5003_50030401_109_dialog_content = "Que ótimo. Comandante Hiiro, você pode finalmente sair da Montanha Nebulosa com um sorriso.",
  ui_story_5003_50030401_110_dialog_content = "Por que diz isso?",
  ui_story_5003_50030401_111_dialog_content = "Sinto que você estava estressada o tempo todo. Eu me preocupei um pouco com você.",
  ui_story_5003_50030401_112_dialog_content = "Obrigada por se preocupar.",
  ui_story_5003_50030401_113_dialog_content = "No início, eu realmente tinha algumas... suspeitas, mas eu sei que tudo vai ficar bem.",
  ui_story_5003_50030401_114_dialog_content = "Meu mestre disse que não queria que eu voltasse pra Montanha Nebulosa, mas não me disse por quê.",
  ui_story_5003_50030401_115_dialog_content = "Pensando bem, talvez ele só quisesse me proteger.",
  ui_story_5003_50030401_116_dialog_content = "Porém, quando meu mestre morreu, seu último desejo era que eu “encontrasse meu futuro na lâmina de Sakae”.",
  ui_story_5003_50030401_117_dialog_content = "Eu não entendi o que isso significava, mas após minha Lâmina Sakae começar a mudar, eu estava determinada a voltar pra Montanha Nebulosa.",
  ui_story_5003_50030401_118_dialog_content = "Embora eu ainda não saiba por que, desde que eu possa continuar buscando os segredos da Lâmina Sakae, eu um dia saberei.",
  ui_story_5003_50030401_119_dialog_content = "É que parece que não vou conseguir acalmar suas <color=#FFB400>vibrações</color> ainda.",
  ui_story_5003_50030401_120_dialog_content = "Espere. O que quis dizer com “acalmar suas vibrações”?",
  ui_story_5003_50030401_121_dialog_content = "Eu posso senti-la tremendo. Talvez isso pareça ridículo.",
  ui_story_5003_50030401_122_dialog_content = "Mas foi o que aconteceu. A primeira vez foi há sete dias e algumas horas atrás ela tremeu de novo. Essa é a terceira vez agora.",
  ui_story_5003_50030401_123_dialog_content = "<color=#e8d9bb>*Brrr*</color>",
  ui_story_5003_50030401_124_dialog_content = "Esse zumbido... É a lâmina vibrando?",
  ui_story_5003_50030401_125_dialog_content = "Hiiro, esse som... Acho que já ouvi antes no dojo.",
  ui_story_5003_50030401_126_dialog_content = "A arma de Sanki estava tremendo assim como a sua Lâmina Sakae!",
  ui_story_5003_50030401_127_dialog_content = "Mas isso não pode ser. A menos que a lâmina dele...",
  ui_story_5003_50030401_128_dialog_content = "Também seja uma <color=#FFB400>Lâmina Sakae</color>!?",
  ui_story_5003_50030401_129_dialog_content = "Somente chamas abrasadoras e o sangue de Sakae podem transformar uma katana em uma Lâmina Sakae.",
  ui_story_5003_50030401_130_dialog_content = "As forças do mal que atacaram a Família Sakae, meus inimigos...",
  ui_story_5003_50030401_131_dialog_content = "<size=45>Suas espadas estavam cobertas pelo sangue de Sakae e eles queimaram nossa casa!</size>",
  ui_story_5003_50030401_X131_dialog_content = "Quer dizer que Sanki é um desses inimigos!?",
  ui_story_5003_50030501_1_dialog_content = "PlayerName, é a única hipótese que consigo pensar. Ele tem uma Lâmina Sakae!",
  ui_story_5003_50030501_2_dialog_content = "O mestre me disse antes de morrer que sua espada foi banhada no sangue de Sakae.",
  ui_story_5003_50030501_3_dialog_content = "Após o revenimento com chamas, a lâmina renascerá e se tornará uma Lâmina Sakae.",
  ui_story_5003_50030501_4_dialog_content = "As forças do mal do Oriente que massacraram a Família Sakae... Aqueles que chamamos de inimigos...",
  ui_story_5003_50030501_5_dialog_content = "Suas espadas estavam cobertas pelo sangue de Sakae e eles queimaram nossa casa!",
  ui_story_5003_50030501_6_dialog_content = "Mas a velhinha deve conhecer Sanki, então por que ela não disse nada?",
  ui_story_5003_50030501_7_dialog_content = "A velhinha é a cuidadora da família, ela não sabe muito sobre Sakae.",
  ui_story_5003_50030501_8_dialog_content = "Talvez ela não soubesse a verdadeira identidade do Sanki?",
  ui_story_5003_50030501_9_dialog_content = "PlayerName, vamos voltar logo pra Montanha Nebulosa!",
  ui_story_5003_50030501_10_dialog_content = "Você sabe o tanto de sangue que eu derramei por este dia?",
  ui_story_5003_50030501_11_dialog_content = "Olhe essas lâminas... <color=#FFB400>Toda vez que chego perto do selo, elas começam a tremer</color>! E rugir!",
  ui_story_5003_50030501_12_dialog_content = "Agora só preciso de uma última coisa: a Hiiro da Família Sakura!",
  ui_story_5003_50030501_13_dialog_content = "Aí eu finalmente poderei realizar o que tanto almejei por todos esses anos!",
  ui_story_5003_50030501_14_dialog_content = "Como ousa deixá-la ir!?",
  ui_story_5003_50030501_15_dialog_content = "Acalme-se, Sanki. Deixe-me explicar...",
  ui_story_5003_50030501_16_dialog_content = "Você quer que eu me acalme? Você quer que eu escute mais das suas mentiras!?",
  ui_story_5003_50030501_17_dialog_content = "Você me afastou e deixou o cara ir de propósito. E depois deixou a Hiiro ir embora! Foi isso que você fez!",
  ui_story_5003_50030501_18_dialog_content = "Você sabe quem eu sou desde o primeiro dia que nos vimos! Você estava planejando me deter desde o começo, né!",
  ui_story_5003_50030501_19_dialog_content = "Eu não estava pensando em te matar. Você acha que pode me derrotar? É isso?",
  ui_story_5003_50030501_20_dialog_content = "Não, me escute. Você não pode destruir aquela coisa protegida pelo selo. Se destruir isso, a Montanha Nebulosa irá...",
  ui_story_5003_50030501_21_dialog_content = "Cale a boca! Eu não quero ouvir mais nenhuma palavra sua!",
  ui_story_5003_50030501_X21_dialog_content = "Você não acha mesmo que eu vou te matar, né?",
  ui_story_5003_50030501_X23_dialog_content = "Me dê seu sangue.",
  ui_story_5003_50030501_22_dialog_content = "Sanki eu já te disse antes... Eu não sou um membro da Família Sakura!",
  ui_story_5003_50030501_23_dialog_content = "Mas eu não testei seu sangue ainda!",
  ui_story_5003_50030501_X22_dialog_content = "Eu nunca vou me esquecer da ira de Underwell.",
  ui_story_5003_50030501_24_dialog_content = "Não é natural que o derrotado desista da sua vida? Se você perde, você deve pagar o preço em sangue.",
  ui_story_5003_50030501_25_dialog_content = "E quando eu abrir a porta e destruir o que estiver dentro, minha vingança estará completa.",
  ui_story_5003_50030501_26_dialog_content = "Não é mesmo, Sakae?",
  ui_story_5003_50030501_27_dialog_content = "Eu quase me esqueci por que eu vim, mas você me fez lembrar.",
  ui_story_5003_50030501_28_dialog_content = "Eu devia te agradecer, Hiiro. Você caiu nas minhas mãos.",
  ui_story_5003_50030501_29_dialog_content = "Haha... Hahahahaha...",
  ui_story_5003_50030501_30_dialog_content = "Haha... O que foi que meu pai me disse na noite que ele partiu? Eu já me esqueci.",
  ui_story_5003_50030501_31_dialog_content = "Sanki! Deixe-a em paz!",
  ui_story_5003_50030501_32_dialog_content = "Hiiro!?",
  ui_story_5003_50030501_33_dialog_content = "Hahaha! Olhe, velhinha! A sua Hiiro voltou! Ela voltou por conta própria!",
  ui_story_5003_50030501_34_dialog_content = "H... Hiiro! Não se precipite...",
  ui_story_5003_50030501_35_dialog_content = "Se você tem algum ressentimento contra mim, me ataque. Não precisa machucá-la.",
  ui_story_5003_50030501_36_dialog_content = "É claro. Desde que você fique aqui, eu liberto ela.",
  ui_story_5003_50030501_37_dialog_content = "Tudo bem, eu prometo. Vice, PlayerName... Protejam a Vovó.",
  ui_story_5003_50030501_38_dialog_content = "Vovó, venha até mim!",
  ui_story_5003_50030501_39_dialog_content = "Não se preocupem! Sanki não vai me machucar! Ele não é nosso inimigo! Ele é filho do carpinteiro!",
  ui_story_5003_50030501_40_dialog_content = "Cale a boca! Nem mais uma palavra!",
  ui_story_5003_50030501_41_dialog_content = "Hiiro! Depois que eu usar o seu sangue pra quebrar o selo, eu te conto tudo.",
  ui_story_5003_50030501_42_dialog_content = "Eu só preciso que você me diga de onde veio a lâmina na sua mão. Você é um inimigo da minha família!?",
  ui_story_5003_50030501_43_dialog_content = "Se você for, eu vou ter minha vingança!",
  ui_story_5003_50030501_X43_dialog_content = "...",
  ui_story_5003_50030501_X44_dialog_content = "Que piada!",
  ui_story_5003_50030501_X45_dialog_content = "O quê!?",
  ui_story_5003_50030501_44_dialog_content = "Você é corajoso pra continuar tagarelando sobre vingança!?",
  ui_story_5003_50030501_45_dialog_content = "As pessoas de Underwell foram envolvidas sem motivo na luta entre Sakae e seus inimigos e eles foram massacrados em uma só noite.",
  ui_story_5003_50030501_46_dialog_content = "Eu coloquei um fim a essas forças do mal. Eu matei todos aqueles inimigos! Olhe as Lâminas Sakae nas minhas mãos!",
  ui_story_5003_50030501_47_dialog_content = "As lâminas que peguei dos inimigos são prova da minha vingança! O que fiz foi uma vingança real!",
  ui_story_5003_50030501_48_dialog_content = "E quanto a você, eu vou tirar sua vida e usá-la para destruir <size=45>a fonte de tudo isso, a coisa atrás do selo</size>!",
  ui_story_5003_50030501_49_dialog_content = "Não posso deixar você destruir o objeto importante selado aqui! A segurança da Montanha Nebulosa depende disso!",
  ui_story_5003_50030501_50_dialog_content = "Chega de conversa! Hiiro, você não merece essa Lâmina! Sakae Shigeo, hoje eu reivindico minha oitava lâmina!",
  ui_story_5003_50030501_51_dialog_content = "O destino da Montanha Nebulosa e essa Lâmina Sakae... jamais cairão nas suas mãos!",
  ui_story_5003_50030501_52_dialog_content = "O que foi? Você não é a orgulhosa aprendiz de Sakae Shigeo?",
  ui_story_5003_50030501_53_dialog_content = "Hahaha! Você não consegue nem revidar!?",
  ui_story_5003_50030501_54_dialog_content = "Hiiro! Concentre-se!",
  ui_story_5003_50030501_55_dialog_content = "Concentre sua mente e dê à lâmina tudo que você tiver.",
  ui_story_5003_50030501_56_dialog_content = "Tudo que eu tiver...",
  ui_story_5003_50030501_57_dialog_content = "Zakura, Sakae, poder transitório...",
  ui_story_5003_50030501_58_dialog_content = "E uma determinação que teme a morte. Isso é tudo que eu possuo.",
  ui_story_5003_50030501_59_dialog_content = "!!!",
  ui_story_5003_50030501_60_dialog_content = "Você perdeu, Sanki.",
  ui_story_5003_50030501_61_dialog_content = "Haha... *tosse*",
  ui_story_5003_50030501_62_dialog_content = "Eu perdi... Então, mate-me.",
  ui_story_5003_50030501_63_dialog_content = "O vencedor decide o destino do derrotado. Quando eu mato meus inimigos, eu digo a eles a mesma coisa.",
  ui_story_5003_50030501_66_dialog_content = "Espere! Hiiro! Não mate ele!",
  ui_story_5003_50030501_67_dialog_content = "Eu sei. Ele não é meu “inimigo”. Diga quem ele é, Vovó.",
  ui_story_5003_50030501_68_dialog_content = "Ele é filho do carpinteiro de Underwell que construiu a sala secreta para a Família Sakae.",
  ui_story_5003_50030501_69_dialog_content = "A família dele... foi vítima de um massacre naquela noite.",
  ui_story_5003_50030501_70_dialog_content = "*Tosse* Meu pai... concordou em construir a câmara secreta.",
  ui_story_5003_50030501_71_dialog_content = "Para que eu pudesse me tornar um aprendiz do Dojo Sakae.",
  ui_story_5003_50030501_72_dialog_content = "Tudo por causa daquela coisa atrás do selo! A causa de toda essa morte e destruição!",
  ui_story_5003_50030501_74_dialog_content = "Não, o objeto selado aqui é muito importante para Cloud Mountain, então todos sacrificaram tudo para protegê-lo...",
  ui_story_5003_50030501_75_dialog_content = "Chega dessa baboseira! Vá em frente!",
  ui_story_5003_50030501_76_dialog_content = "Tudo bem...",
  ui_story_5003_50030501_77_dialog_content = "...",
  ui_story_5003_50030501_S77_dialog_content = "Você só cortou meu cabelo?",
  ui_story_5003_50030501_X77_dialog_content = "Por que você está fazendo isso!? Você não vai acabar comigo?",
  ui_story_5003_50030501_X78_dialog_content = "Eu já acabei com você.",
  ui_story_5003_50030501_78_dialog_content = "“Você” está morto. O “você” que estava obcecado pela vingança foi derrotado.",
  ui_story_5003_50030501_79_dialog_content = "Eu espero que você possa esquecer e colocar um fim nisso. Desista dessa ideia de destruir o selo.",
  ui_story_5003_50030501_80_dialog_content = "Eu prefiro que você me mate em vez de me fazer um desertor covarde como você e o Sakae Shigeo!",
  ui_story_5003_50030501_81_dialog_content = "Teve uma época que eu não entendia como ele poderia fugir numa situação dessas.",
  ui_story_5003_50030501_82_dialog_content = "Mas Sakae Shigeo... Meu mestre... Ele nunca teve medo de encarar a morte.",
  ui_story_5003_50030501_X82_dialog_content = "Ele tentou me levar, a “chave” do selo, para longe daqui.",
  ui_story_5003_50030501_83_dialog_content = "Mestre, sua velha ferida reabriu?!",
  ui_story_5003_50030501_84_dialog_content = "Os Eclipsitas vão chegar aqui logo e ninguém pode defender o caminho para o abrigo a não ser nós.",
  ui_story_5003_50030501_85_dialog_content = "Mas meu machucado é muito grave para eu continuar lutando.",
  ui_story_5003_50030501_X85_dialog_content = "Chegou minha hora de morrer.",
  ui_story_5003_50030501_86_dialog_content = "Hiiro, depois que eu morrer, pegue minha lâmina. Ela se tornará uma verdadeira Lâmina Sakae.",
  ui_story_5003_50030501_87_dialog_content = "Chamas Abrasadoras e o sangue de Sakae... Vão fazer essa espada ficar muito poderosa. Essa Lâmina Sakae...",
  ui_story_5003_50030501_88_dialog_content = "vai te deixar muito poderosa. Ela vai lhe conceder o poder para derrotar Eclipsitas.",
  ui_story_5003_50030501_89_dialog_content = "Espero que você possa ver seu brilhante futuro na Lâmina Sakae.",
  ui_story_5003_50030501_90_dialog_content = "O mestre tinha esperança que eu pudesse ver o futuro na Lâmina Sakae.",
  ui_story_5003_50030501_91_dialog_content = "Mas eu não sabia que “futuro” era esse.",
  ui_story_5003_50030501_92_dialog_content = "Eu não compreendia até ver você.",
  ui_story_5003_50030501_93_dialog_content = "O que quer dizer com “até me ver”?",
  ui_story_5003_50030501_94_dialog_content = "Assim como você, eu voltei para a Montanha Nebulosa por ódio.",
  ui_story_5003_50030501_95_dialog_content = "Mas agora eu sei de tudo.",
  ui_story_5003_50030501_96_dialog_content = "O objeto selado mantém a barreira que protege a Montanha Nebulosa. Todos morreram protegendo a Montanha Nebulosa.",
  ui_story_5003_50030501_97_dialog_content = "Então eu não posso deixá-lo quebrar o selo e destruir o que está aqui.",
  ui_story_5003_50030501_98_dialog_content = "Mas eu nunca vou te matar.",
  ui_story_5003_50030501_102_dialog_content = "Eu reconheço sua técnica. Somos da mesma escola.",
  ui_story_5003_50030501_103_dialog_content = "...",
  ui_story_5003_50030501_104_dialog_content = "Pai! O Dojo Sakae vai me aceitar?",
  ui_story_5003_50030501_105_dialog_content = "É claro! À partir da próxima semana, você será um aprendiz do Dojo Sakae!",
  ui_story_5003_50030501_106_dialog_content = "A Família Sakae é maravilhosa! Eles protegem toda a Montanha Nebulosa. Estude bastante depois que se juntar a eles!",
  ui_story_5003_50030501_107_dialog_content = "Ok, Pai! Eu vou dar o meu melhor!",
  ui_story_5003_50030501_108_dialog_content = "O sol nasceu. É hora de ir para a Montanha Nebulosa. Eu vou esperar por você no dojo.",
  ui_story_5003_50030501_109_dialog_content = "Bem, o sol já nasceu. Está na hora de eu partir.",
  ui_story_5003_50030501_X109_dialog_content = "Minha presença aqui afetará a estabilidade do selo. Eu jamais poderei voltar para a Montanha Nebulosa.",
  ui_story_5003_50030501_X110_dialog_content = "Espero que ninguém tente descobrir o que está lacrado aqui e que a Montanha Nebulosa fique finalmente em paz.",
  ui_story_5003_50030501_X111_dialog_content = "Se alguém tentar quebrar o selo, eles vão ter que pegar meu sangue primeiro.",
  ui_story_5003_50030501_X112_dialog_content = "E eu?",
  ui_story_5003_50030501_X113_dialog_content = "Você pode tentar pegar meu sangue quantas vezes quiser.",
  ui_story_5003_50030501_X114_dialog_content = "Mas somos aprendizes do Dojo Sakae. Eu vou considerar isso como uma “luta”.",
  ui_story_5003_50030501_110_dialog_content = "Hum... Parece que Sanki não quer vir se despedir de vocês.",
  ui_story_5003_50030501_111_dialog_content = "Tudo bem. Eu não esperava isso dele.",
  ui_story_5003_50030501_112_dialog_content = "Eu o ensinei uma dura lição esperando que ele desista da sua vingança. Então não posso culpá-lo por guardar rancor no seu coração.",
  ui_story_5003_50030501_113_dialog_content = "Não se preocupe. Não acho que ele te odeie.",
  ui_story_5003_50030501_S113_dialog_content = "O dia que ele descobriu sobre a sala secreta debaixo do hotel... Eu tinha planejado proteger a entrada com a minha vida.",
  ui_story_5003_50030501_S114_dialog_content = "Mas ele abaixou sua arma de repente e parou de tentar entrar à força.",
  ui_story_5003_50030501_S115_dialog_content = "Depois disso, ele começou a vagar por aqui, sempre perguntando como as coisas estavam indo no hotel.",
  ui_story_5003_50030501_S116_dialog_content = "Aos poucos, ele se abriu comigo sobre sua vida e até ajudou Tweety com suas tarefas.",
  ui_story_5003_50030501_S117_dialog_content = "Quando eu disse a ele que não havia mais descendentes da Família Sakura, e que o selo não poderia mais ser quebrado...",
  ui_story_5003_50030501_S118_dialog_content = "Eu o vi respirar aliviado.",
  ui_story_5003_50030501_S119_dialog_content = "Naquela hora, eu senti que talvez ele também precisasse de uma razão para desistir do seu caminho de vingança.",
  ui_story_5003_50030501_S120_dialog_content = "Eu escondi a sua existência dele e também não contei o segredo do selo. A culpa foi toda minha.",
  ui_story_5003_50030501_S121_dialog_content = "Eu sei que você queria proteger o segredo do selo. Ninguém tem culpa.",
  ui_story_5003_50030501_114_dialog_content = "Vovó, Kentalo quer banhar nas fontes telmais. Eu disse pla ele que não estava plonta ainda, mas ele pulou pala limpá-la sozinho.",
  ui_story_5003_50030501_115_dialog_content = "Kentalo estava segulando um monte de espadas quando ele pulou...",
  ui_story_5003_50030501_116_dialog_content = "Hehe, eu acho que ele só queria limpá-las. Daqui a pouco ele sai com elas.",
  ui_story_5003_50030501_117_dialog_content = "Ele é uma boa criança com um bom coração. E ele se importa com a Montanha Nebulosa, mas sua vida não tem sido fácil e sua mente está um pouco confusa.",
  ui_story_5003_50030501_S122_dialog_content = "Eu nunca achei que ele iria nos machucar de verdade.",
  ui_story_5003_50030501_118_dialog_content = "Embora eu acredite no seu julgamento, eu espero que você não seja obrigada a encarar uma situação perigosa como essa sozinha.",
  ui_story_5003_50030501_119_dialog_content = "Tweety, Taki e eu... Se você precisar conversar, você tem amigos em quem confiar.",
  ui_story_5003_50030501_120_dialog_content = "Quanto ao Sanki, vocês podiam conversar sobre os planos dele. Eu me preocupo que após o fim das férias da Tweety, o hotel vai ficar com pouca gente.",
  ui_story_5003_50030501_121_dialog_content = "Talvez o Sanki possa ficar aqui e ajudá-la com o hotel.",
  ui_story_5003_50030501_122_dialog_content = "Não se preocupe se ele invadir o dojo de novo. Se alguma coisa acontecer, a Lâmina Sakae vai me avisar.",
  ui_story_5003_50030501_123_dialog_content = "Muito bem, minha criança. Não se preocupe.",
  ui_story_5003_50030501_124_dialog_content = "Bem, eu nunca imaginei que você fosse trazer tanto drama consigo.",
  ui_story_5003_50030501_125_dialog_content = "Senhor Taki, do que está piando?",
  ui_story_5003_50030501_126_dialog_content = "Não, não, não se preocupe comigo. Eu só estou de férias.",
  ui_story_5003_50030501_127_dialog_content = "Adeus.",
  ui_story_5003_50030501_128_dialog_content = "Mestle Taki saiu antes da Hiilo??",
  ui_story_5003_50030501_129_dialog_content = "Eu acho que ele está indo na mesma direção de antes. Está indo para a Rua Spa.",
  ui_story_5003_50030501_130_dialog_content = "Talvez esteja indo a negócios como sempre?",
  ui_story_5003_50030501_131_dialog_content = "Celto! Isso palece com ele!",
  ui_story_5003_50030501_132_dialog_content = "Está ficando tarde. Eu devo ir também.",
  ui_story_5003_50030501_133_dialog_content = "Cuidem-se, pessoal.",
  ui_story_5003_50030501_134_dialog_content = "Ei! Hiiro!",
  ui_story_5003_50030501_135_dialog_content = "Você não quer sua Lâmina Sakae?",
  ui_story_5003_50030501_136_dialog_content = "Minha Lâmina Sakae nunca sai do meu lado. Eu não entendo do que está falando.",
  ui_story_5003_50030501_137_dialog_content = "Eu tenho sete delas aqui. Você não quer?",
  ui_story_5003_50030501_138_dialog_content = "É claro que não. Como eu poderia pegar suas Lâminas Sakae?",
  ui_story_5003_50030501_139_dialog_content = "<size=30>Espero que você possa ver seu brilhante futuro na Lâmina Sakae.</size>",
  ui_story_5003_50030501_140_dialog_content = "Hã? O que você disse?",
  ui_story_5003_50030501_141_dialog_content = "Nada, só estava falando sozinha.",
  ui_story_5003_50030501_142_dialog_content = "Sanki, meu colega aprendiz, você deve vigiar o dojo com a Vovó.",
  ui_story_5003_50030501_143_dialog_content = "Eu...",
  ui_story_5003_50030501_144_dialog_content = "Eu confio em você.",
  ui_story_5003_50030501_145_dialog_content = "Tanto faz! Se você não quer as lâminas, deixe pra lá!",
  ui_story_5003_50030501_146_dialog_content = "Se você quiser vigiar, então faça você mesma! Está tudo acabado pra mim!",
  ui_story_5003_50030501_147_dialog_content = "Adeus!",
  ui_story_5003_50030501_148_dialog_content = "Esse cara...",
  ui_story_5003_50030501_149_dialog_content = "Eu diria que sua mente está bem confusa.",
  ui_story_5003_50030501_150_dialog_content = "Comandante Hiiro, PlayerName geralmente chama esse tipo de pessoa de tsundere.",
  ui_story_5003_50030501_151_dialog_content = "Vice, não mude de assunto assim de repente!",
  ui_story_5003_50030501_152_dialog_content = "Vice, PlayerName...",
  ui_story_5003_50030501_153_dialog_content = "Desculpe, Comandante! Sabemos que não é a hora certa pra ficar brincando!",
  ui_story_5003_50030501_154_dialog_content = "Não era isso que eu ia dizer.",
  ui_story_5003_50030501_155_dialog_content = "Obrigada por me ajudarem e confiarem em mim. Vamos. Devemos voltar.",
  ui_story_5003_50030501_156_dialog_content = "Tudo bem, Soroz pronto para sair!",
  ui_story_5003_50030501_157_dialog_content = "Façam uma boa viagem, minhas crianças.",
  ui_story_5003_50030501_158_dialog_content = "Tchau, tchau! Não se esqueçam de nos enviar uma calta pela União Mensageila!",
  ui_story_5003_50030501_159_dialog_content = "Claro. Vou pedir para alguém da União Mensageira te enviar as cartas.",
  ui_story_5003_50030501_160_dialog_content = "Adeus, Montanha Nebulosa."
}
return config
